def _sha(b: bytes) -> str: return hashlib.sha256(b).hexdigest()


def _read(p: str) -> bytes:
    if not os.path.isfile(p) or os.path.islink(p): raise InputContractError(f"registered D4C-2 record missing: {p}")
    return open(p, "rb").read()


def _json(p: str):
    b = _read(p)
    def pairs(items):
        out = {}
        for k, v in items:
            if k in out: raise ValueError(f"duplicate key {k}")
            out[k] = v
        return out
    try: return b, json.loads(b.decode("utf-8"), object_pairs_hook=pairs, parse_constant=lambda v: (_ for _ in ()).throw(ValueError(v)))
    except ValueError as ex: raise InputContractError(f"registered D4C-2 record is not strict finite JSON: {p}") from ex


def _payload_sha(doc: dict, key: str) -> str: return _sha(json.dumps({k: v for k, v in doc.items() if k != key}, sort_keys=True, allow_nan=False, ensure_ascii=False).encode("utf-8"))
def _root(root: str) -> str: return os.path.join(os.path.abspath(root), "registered_assets", "d4c2")
def _fail(key: str, what: str): raise InputContractError(f"{key}: {what}")


def _teq(a, b) -> bool:
    if type(a) is not type(b): return False
    if isinstance(a, dict): return set(a) == set(b) and all(_teq(a[k], b[k]) for k in a)
    if isinstance(a, (list, tuple)): return len(a) == len(b) and all(_teq(x, y) for x, y in zip(a, b))
    return a == b


def _check_files(base: str, expected: dict, key: str) -> dict:
    """Every registered member exists with exactly the constant SHA / bytes; no extra members under the registered directory."""
    found = {}
    for dp, _, fs in os.walk(base):
        for f in fs: p = os.path.join(dp, f); found[os.path.relpath(p, base).replace(os.sep, "/")] = p
    if sorted(found) != sorted(expected): _fail(key, f"registered member set differs from the constants: {sorted(set(found) ^ set(expected))}")
    out = {}
    for rel, p in found.items():
        b = _read(p)
        if _sha(b) != expected[rel]["sha256"] or len(b) != expected[rel]["bytes"]: _fail(key, f"registered member {rel} differs from the accepted original")
        out[rel] = dict(sha256=_sha(b), bytes=len(b))
    return out


def _check_archive(path: str, const: dict, members: dict, key: str) -> dict:
    b = _read(path)
    if _sha(b) != const["sha256"] or len(b) != const["bytes"]: _fail(key, "inner archive bytes differ from the accepted original")
    z = zipfile.ZipFile(path); got = {}
    for i in z.infolist():
        if i.is_dir(): continue
        if i.filename.startswith("/") or ".." in i.filename: _fail(key, "archive member path")
        d = z.read(i.filename); got[i.filename] = dict(sha256=_sha(d), bytes=len(d))
    if got != members: _fail(key, "archive members differ from the registered extracted members")
    return dict(file=os.path.basename(path), sha256=_sha(b), bytes=len(b), members=len(got))


def _check_doc(path: str, const: dict, key: str) -> dict:
    b = _read(path)
    if _sha(b) != const["sha256"] or len(b) != const["bytes"]: _fail(key, f"{os.path.basename(path)} differs from the registered constant")
    return dict(file=os.path.basename(path), sha256=_sha(b), bytes=len(b))


# ------------------------------------------------------------------------------------------------------------------------------------ the historical source epoch
def _check_source(root: str) -> dict:
    K = "source"; R = _root(root); p = os.path.join(R, "source", SOURCE["inventory"]["file"]); b, inv = _json(p)
    if _sha(b) != SOURCE["inventory"]["sha256"] or len(b) != SOURCE["inventory"]["bytes"]: _fail(K, "registered copy of the 0.112.0 inventory differs from the historical bytes")
    if inv.get("engine_version") != SOURCE["engine_version"] or (inv.get("d_sha256") or {}).get("d/d4c1_calibration.py") != SOURCE["script_sha256"] or inv["d_sha256"].get("d/d3_pins.json") != SOURCE["pins_sha256"] or inv["d_sha256"].get("d/MirrorTopology_Step1_D4C2_screen_v0.1.ipynb") != SOURCE["screen_notebook_sha256"] or not isinstance(inv.get("modules"), dict) or len(inv["modules"]) != 61: _fail(K, "historical inventory does not name the execution source")
    return dict(commit=SOURCE["commit"], engine_version=SOURCE["engine_version"], inventory=dict(SOURCE["inventory"]), script_sha256=SOURCE["script_sha256"], pins_sha256=SOURCE["pins_sha256"], screen_notebook_sha256=SOURCE["screen_notebook_sha256"], source_zip_sha256=SOURCE["source_zip_sha256"], modules=dict(inv["modules"]), registered_assets_sha256=dict(inv.get("registered_assets_sha256") or {}))


def _registered_context(root: str, ctx: TwelveContext):
    """The registered W2 decisions and pseudo columns (D4C-0 loaders) and the registered grid / manifest / configuration ids of the first wave."""
    from .d4c0_registry import load_registered_w2_context, load_registered_pseudo_columns
    from .grid_registry import load_registry
    from .grid_manifest import build_configuration_manifest
    w2ctx, w2view = load_registered_w2_context(root, ctx); cols = load_registered_pseudo_columns(root, ctx)
    reg = load_registry(os.path.join(root, "tests", "assets", "a7_circle_geometry.csv"), os.path.join(root, "tests", "assets", "a6_observer_design_points.json")); man = build_configuration_manifest(reg)
    cfg: Dict[str, Dict[str, list]] = {}
    for c in ctx.d2_spec["configurations"].values(): cfg.setdefault(c["family"], {}).setdefault(c["size_id"], []).append(c["config_id"])
    cfg = {f: {s: sorted(v) for s, v in d.items()} for f, d in cfg.items()}
    dec = {k: w2ctx.decision_for(k, w2ctx.context_sha256) for k in w2ctx.decisions}
    pid = dict(n=cols["n"], sha256_T1=cols["identity"]["T1_sha256"], sha256_T2=cols["identity"]["T2_sha256"])
    return dict(w2ctx=w2ctx, w2view=w2view, decisions=dec, cols=cols, pid=pid, reg=reg, man=man, config_ids=cfg)


# ------------------------------------------------------------------------------------------------------------------------------------ screens
def _check_screen(root: str, ctx: TwelveContext, F: str, src: dict, rc: dict) -> dict:
    from .infeasibility import bind_screen_record
    from . import serialization as ser
    K = f"screen_{F}"; R = _root(root); C = SCREENS[F]; base = os.path.join(R, C["registered_dir"]); A = C["attempt"]; L = C["execution_lock"]; d2l = ctx._d["d2_ledger"]
    files = _check_files(base, C["files"], K); arc = _check_archive(os.path.join(R, "screens", "archives", C["archive"]["file"]), C["archive"], files, K); nb = _check_doc(os.path.join(R, "screens", "notebooks", C["executed_notebook"]["file"]), C["executed_notebook"], K)
    lb, lock = _json(os.path.join(base, "d4c1_screen_lock.json")); fb, fin = _json(os.path.join(base, "d4c1_screen_final_record.json")); rb, run = _json(os.path.join(base, f"run_{A}", f"d4c1_screen_{F}_run.json")); sb, scr = _json(os.path.join(base, f"run_{A}", C["screen"]["file"]))
    # lock: the historical epoch (commit / inventory / script / pins / engine / registered assets), this family, the whole range, the campaign / commitment
    if _sha(lb) != L["lock_file_sha256"] or _sha(fb) != C["final_file_sha256"] or _sha(rb) != C["run_file_sha256"]: _fail(K, "lock / final / run record bytes differ from the registered constants")
    if lock.get("schema") != "d4c1_screen_launcher_lock_v1" or lock.get("commit") != L["commit"] or lock.get("commit") != SOURCE["commit"] or lock.get("engine") != SOURCE["engine_version"] or lock.get("inventory_sha256") != SOURCE["inventory"]["sha256"] or lock.get("script_sha256") != SOURCE["script_sha256"] or lock.get("inventory_script_sha256") != SOURCE["script_sha256"] or lock.get("pins_sha256") != SOURCE["pins_sha256"] or lock.get("locked_utc") != L["locked_utc"]: _fail(K, "execution lock differs from the registered constants / the historical source epoch")
    if lock.get("family") != F or lock.get("row_range") is not None or lock.get("target_commitment") != TARGET_COMMITMENT or lock.get("campaign_id") != CAMPAIGN_ID or lock.get("d2_run_root") != L["d2_run_root"] or lock.get("out_root") != L["out_root"] or lock.get("stage_local") is not True: _fail(K, "execution lock settings differ from the execution GO")
    ra = lock.get("registered_assets_sha256")
    if not isinstance(ra, dict) or ra != L["registered_assets_sha256"] or any(src["registered_assets_sha256"].get(k) != v for k, v in ra.items()) or len(ra) < 9: _fail(K, "locked registered-asset SHA map differs from the historical inventory")
    if L["d2_run_root"].rstrip("/") != d2l["families"][F]["run_root"].rstrip("/") + "/out/d2": _fail(K, "locked D-2 run root differs from the registered D-2 ledger run root")
    # final record: the accepted complete, failure-free, non-fallback launch of THIS attempt; record_sha256 == the run record bytes; live source observations == lock
    if fin.get("schema") != "d4c1_screen_launcher_final_record_v1" or fin.get("attempt_id") != A or fin.get("lock_sha256") != L["lock_file_sha256"] or not _teq(fin.get("lock"), lock) or fin.get("stage") != "complete" or fin.get("exit_code") != 0 or fin.get("launcher_fallback") is not False or fin.get("gates_ok") is not True or fin.get("bindings_ok") is not True or fin.get("evidence_ok") is not True or fin.get("failures") != [] or fin.get("exception") is not None or fin.get("screen_complete") is not True or fin.get("D4C1_SCREEN_COMPLETE") is not True or fin.get("row_range") is not None or fin.get("record_sha256") != _sha(rb) or fin.get("record_stage") != "complete" or fin.get("record_failures") != [] or os.path.basename(str(fin.get("run_dir"))) != f"run_{A}": _fail(K, "launcher final record is not the accepted success record of this attempt")
    for pfx in ("precheck", "prelaunch"):
        s = (fin.get("bindings") or {}).get(f"live_source_{pfx}") or {}
        if s.get("head") != SOURCE["commit"] or s.get("clean") is not True or s.get("inventory_sha256") != SOURCE["inventory"]["sha256"] or s.get("script_sha256") != SOURCE["script_sha256"] or s.get("inventory_script_sha256") != SOURCE["script_sha256"] or s.get("pins_sha256") != SOURCE["pins_sha256"] or s.get("engine") != SOURCE["engine_version"] or s.get("registered_assets_sha256") != ra: _fail(K, f"live source observation ({pfx}) differs from the lock")
    # run record: the trusted REQUIRED_SCREEN of the producer (constant), formal scope, the historical source, this attempt, published evidence, D-2 binding, environment
    g = run.get("gates") if isinstance(run.get("gates"), dict) else {}
    if run.get("schema") != "d4c1_run_record_v1" or run.get("mode") != "screen" or run.get("family") != F or run.get("stage") != "complete" or run.get("failures") != [] or run.get("selftest") is not False or run.get("formal") is not True or run.get("probe") is not False or run.get("instrument") is not False or run.get("subpartial") is not False or run.get("row_range") is not None or run.get("profile") != "production_official": _fail(K, "script run record is not a formal complete screen run")
    if run.get("required_inventory") != list(SCREEN_REQUIRED) or sorted(g) != sorted(SCREEN_REQUIRED) or not all(g.get(k) is True for k in SCREEN_REQUIRED) or run.get("required_all_true") is not True or run.get("D4C1_SCREEN_COMPLETE") is not True or any(run.get(f) is not False for f in FLAGS if f != "D4C1_SCREEN_COMPLETE"): _fail(K, "script run record is not the accepted success record (trusted REQUIRED_SCREEN gates / flags)")
    a_ = run.get("attempt") if isinstance(run.get("attempt"), dict) else {}; s_ = run.get("source") if isinstance(run.get("source"), dict) else {}
    if a_.get("attempt_id") != A or a_.get("launcher_lock_sha256") != L["lock_file_sha256"] or s_.get("script_sha256") != SOURCE["script_sha256"] or s_.get("inventory_sha256") != SOURCE["inventory"]["sha256"] or s_.get("pins_sha256") != SOURCE["pins_sha256"] or s_.get("engine_version") != SOURCE["engine_version"] or run.get("engine_version") != SOURCE["engine_version"] or run.get("pins_sha256") != SOURCE["pins_sha256"] or run.get("campaign_id") != CAMPAIGN_ID or run.get("target_commitment") != TARGET_COMMITMENT: _fail(K, "script run record not bound to this attempt / lock / the historical source epoch")
    env = run.get("env") or {}
    if not recorded_environment_registered(env, ctx._d["pins"]) or (run.get("env_gate") or {}).get("versions_ok") is not True or run["env_gate"].get("pools_ok") is not True: _fail(K, "recorded environment differs from the registered environment (current or registered history)")
    pe = run.get("published_evidence") or {}
    if set(pe) != {C["screen"]["file"]} or pe[C["screen"]["file"]] != dict(sha256=C["screen"]["sha256"], bytes=C["screen"]["bytes"]) or _sha(sb) != C["screen"]["sha256"] or len(sb) != C["screen"]["bytes"]: _fail(K, "published screen record identity")
    d2 = (run.get("inputs") or {}).get("d2") or {}
    if d2.get("run_id") != d2l["families"][F]["run_id"] or d2.get("registry_sha256") != d2l["families"][F]["records"]["bank_registry_sha256"] or d2.get("run_root", "").rstrip("/") != d2l["families"][F]["run_root"].rstrip("/"): _fail(K, "run record D-2 input binding differs from the registered D-2 ledger")
    rs = run.get("screen") or {}
    if rs.get("screen_sha256") != C["screen"]["content_sha256"] or rs.get("n_rows") != N_ROWS or rs.get("n_blocking") != C["screen"]["n_blocking"] or rs.get("rows") != [0, N_ROWS] or rs.get("w2_applicable") is not True or rs.get("stages_covered") != ["N0", "N4"] or rs.get("ratio_bound_max") != C["screen"]["ratio_bound_max"]: _fail(K, "run record screen summary differs from the registered constants")
    # the screen record itself: unmodified checkers (formal shape; binding to the REGISTERED W2 decisions / columns / grid / configuration ids), whole range exactly once, historical module binding
    scr = ser.from_jsonable(ser.to_jsonable(scr))
    if scr.get("binding", {}).get("screen_sha256") != C["screen"]["content_sha256"] or scr.get("engine_version") != SOURCE["engine_version"] or scr["binding"].get("engine_version") != SOURCE["engine_version"] or scr["binding"].get("modules") != src["modules"]: _fail(K, "screen record provenance differs from the historical source epoch")
    b = bind_screen_record(scr, registry_sha256=rc["reg"].registry_sha256, manifest_sha256=rc["man"].manifest_sha256, w2_context_sha256=rc["w2ctx"].context_sha256, w2_decisions=rc["decisions"], pseudo_identity=rc["pid"], T1=rc["cols"]["T1"], T2=rc["cols"]["T2"], config_ids=rc["config_ids"][F], family=F, campaign_id=CAMPAIGN_ID, target_commitment=TARGET_COMMITMENT)
    if not (b.get("bound") and b.get("formal") and b.get("complete_coverage") and b.get("w2_applicable")) or scr["rows"] != list(range(N_ROWS)) or scr["n_rows"] != N_ROWS or scr["n_blocking"] != C["screen"]["n_blocking"] or not _teq(scr["w2"], C["screen"]["w2"]) or scr["config_ids"] != C["screen"]["config_ids"] or scr["registry_sha256"] != C["screen"]["registry_sha256"] or scr["manifest_sha256"] != C["screen"]["manifest_sha256"] or scr["w2_context_sha256"] != C["screen"]["w2_context_sha256"] or scr["pseudo"] != C["screen"]["pseudo"] or (scr.get("campaign") or {}).get("formal") is not True or scr["campaign"].get("screen") is not True: _fail(K, "screen record not bound to the registered identities / whole range")
    if any(v["trigger"] is True for v in scr["w2"].values()) or not any(v["trigger"] == "unknown" for v in scr["w2"].values()): _fail(K, "the W2 premise (no True, >= 1 unknown) does not hold")
    rows = {x["row"]: dict(kind="screen", family=F, status=dict(support="unknown_or_technical", strong="unknown_or_technical"), source_sha256=scr["binding"]["screen_sha256"], ratio_bounds={s: x["sizes"][s]["ratio_bound"] for s in scr["sizes"]}) for x in scr["results"] if x["blocking"]}   # == blocking_rows_from_screen(scr, formal=True) after the formal check above (not re-checked twice)
    if sorted(rows) != list(range(N_ROWS)) or any(ev["family"] != F or ev["source_sha256"] != C["screen"]["content_sha256"] or ev["status"] != dict(support="unknown_or_technical", strong="unknown_or_technical") for ev in rows.values()): _fail(K, "blocking rows of the screen are not the whole range with the screen's conditional status")
    mp = min(x["sizes"][s]["min_P"] for x in scr["results"] for s in scr["sizes"]); rbmax = {s: max(x["sizes"][s]["ratio_bound"] for x in scr["results"]) for s in scr["sizes"]}
    if mp != C["screen"]["min_P"] or rbmax != C["screen"]["ratio_bound_max"] or max(rbmax.values()) > 2.0 or mp <= 0: _fail(K, "envelope statistics differ from the registered constants")
    return dict(attempt=A, registered_dir=C["registered_dir"], execution_lock=copy.deepcopy(L), records=files, inner_archive=arc, executed_notebook=nb, screen=copy.deepcopy(C["screen"]), blocking_rows=rows, d2=dict(run_id=d2l["families"][F]["run_id"], registry_sha256=d2l["families"][F]["records"]["bank_registry_sha256"]),
                resources=dict(seconds_script=run["seconds"], seconds_launcher=fin["seconds_total"], screen_seconds=run["timings"].get("screen_seconds"), stages_peak_rss_mb=run["stages_peak_rss_mb"], ram_total_bytes=(fin.get("ram") or {}).get("total_bytes"), staging_bytes=(fin.get("staging") or {}).get("input_bytes")), environment={k: env[k] for k in ("python", "numpy", "scipy", "healpy", "camb", "pot")})


# ------------------------------------------------------------------------------------------------------------------------------------ certificate
def _check_certificate(root: str, src: dict, screens: dict, rc: dict) -> dict:
    from .infeasibility import check_certificate, infeasibility_certificate, aggregate_rows, _levels_from_rows, _registered_thresholds, CERT_SCHEMA, CERT_KIND
    from . import serialization as ser
    K = "certificate"; R = _root(root); C = CERTIFICATE; base = os.path.join(R, C["registered_dir"]); out = os.path.join(R, C["out_dir"])
    files = _check_files(base, C["files"], K)
    rb, run = _json(os.path.join(out, "d4c1_certificate_run.json")); cb, cert = _json(os.path.join(out, C["record_file"]["file"]))
    cmd = _read(os.path.join(base, "command.txt")).decode("utf-8"); rcode = _read(os.path.join(base, "rc.txt")).decode("utf-8").strip(); stderr = _read(os.path.join(base, "stderr.txt"))
    if _sha(rb) != C["run_file_sha256"] or _sha(cb) != C["record_file"]["sha256"] or len(cb) != C["record_file"]["bytes"] or _sha(cmd.encode("utf-8")) != C["command_file_sha256"]: _fail(K, "certificate run / record / command bytes differ from the registered constants")
    if rcode != "rc=0" or stderr != b"" or "--mode certificate" not in cmd or any(x in cmd for x in ("--mt", "--phasec", "--probe-n", "--instrument", "--selftest", "--evaluated")) or cmd.count("--screen") != 3 or f"--target-commitment {TARGET_COMMITMENT}" not in cmd or f"--campaign-id {CAMPAIGN_ID}" not in cmd: _fail(K, "certificate consumer command / rc / stderr are not the accepted certificate-only invocation")
    g = run.get("gates") if isinstance(run.get("gates"), dict) else {}; s_ = run.get("source") if isinstance(run.get("source"), dict) else {}
    if run.get("schema") != "d4c1_run_record_v1" or run.get("mode") != "certificate" or run.get("stage") != "complete" or run.get("failures") != [] or run.get("selftest") is not False or run.get("formal") is not True or run.get("probe") is not False or run.get("profile") != "production_official" or run.get("required_inventory") != list(CERT_REQUIRED) or sorted(g) != sorted(CERT_REQUIRED) or not all(g.get(k) is True for k in CERT_REQUIRED) or run.get("required_all_true") is not True or run.get("D4C1_CERTIFICATE_COMPLETE") is not True or any(run.get(f) is not False for f in FLAGS if f != "D4C1_CERTIFICATE_COMPLETE"): _fail(K, "certificate run record is not the accepted complete formal certificate run")
    if s_.get("inventory_sha256") != SOURCE["inventory"]["sha256"] or s_.get("script_sha256") != SOURCE["script_sha256"] or s_.get("pins_sha256") != SOURCE["pins_sha256"] or s_.get("engine_version") != SOURCE["engine_version"] or run.get("engine_version") != SOURCE["engine_version"] or run.get("pins_sha256") != SOURCE["pins_sha256"] or s_.get("mt") is not None or run.get("campaign_id") != CAMPAIGN_ID or run.get("target_commitment") != TARGET_COMMITMENT: _fail(K, "certificate run record not bound to the historical source epoch (producer == consumer == 0.112.0)")
    if (run.get("published_evidence") or {}) != {C["record_file"]["file"]: dict(sha256=C["record_file"]["sha256"], bytes=C["record_file"]["bytes"])} or (run.get("env_gate") or {}).get("matches_registered") is not False or {k: (run.get("env") or {}).get(k) for k in C["consumer_environment"]} != C["consumer_environment"] or "formal sources only" not in str(run.get("source_scope")): _fail(K, "certificate run record publication / consumer environment metadata")
    # the certificate record: pure arithmetic checker (algebra over the families it carries) AND independent re-derivation from the AUTHENTICATED screens
    cert = ser.from_jsonable(ser.to_jsonable(cert)); chk = check_certificate(cert)
    if not chk["ok"] or cert.get("schema") != CERT_SCHEMA or cert.get("kind") != CERT_KIND or cert["binding"]["certificate_sha256"] != C["content_sha256"] or cert.get("engine_version") != SOURCE["engine_version"] or cert["binding"].get("modules") != src["modules"] or cert["binding"].get("engine_version") != SOURCE["engine_version"]: _fail(K, "certificate record identity / provenance differs from the historical epoch")
    if cert["n"] != N_ROWS or cert["pseudo"] != rc["pid"] or list(cert["thresholds"].items()) != list(_registered_thresholds().items()) or cert["campaign"] != dict(id=CAMPAIGN_ID, formal=True) or cert["target_commitment"] != TARGET_COMMITMENT or cert["n_rows_admitted"] != N_ROWS or cert["n_rows_proven"] != N_ROWS: _fail(K, "certificate denominator / pseudo identity / thresholds / campaign differ from the registered constants")
    srcs = cert.get("sources") or []
    if len(srcs) != 3 or [s.get("family") for s in srcs] != list(FAMILIES): _fail(K, "certificate sources are not the three screens in order")
    for s, F in zip(srcs, FAMILIES):
        S = screens[F]; want = C["sources"][FAMILIES.index(F)]
        if s.get("kind") != "screen" or (s.get("attempt") or {}).get("attempt_id") != S["attempt"] or s.get("screen_sha256") != S["screen"]["content_sha256"] or s.get("sha256") != S["screen"]["sha256"] or s.get("run_sha256") != SCREENS[F]["run_file_sha256"] or s.get("rows") != [0, N_ROWS] or s.get("n_blocking") != N_ROWS or s.get("complete_coverage") is not True or s.get("formal") is not True or s.get("file") != S["screen"]["file"]: _fail(K, f"certificate source {F} does not name the registered screen")
        if dict(kind=s["kind"], family=s["family"], attempt_id=s["attempt"]["attempt_id"], screen_sha256=s["screen_sha256"], file_sha256=s["sha256"], run_sha256=s["run_sha256"], rows=s["rows"], n_blocking=s["n_blocking"]) != want: _fail(K, f"certificate source {F} differs from the registered constant")
    if (run.get("sources") or []) != srcs: _fail(K, "certificate run record sources differ from the record")
    # independent re-derivation from the authenticated screens: families / evidence per global row exactly once; levels == the pure re-derivation; no technical rows
    fam_rows = {r: {F: dict(support="unknown_or_technical", strong="unknown_or_technical") for F in FAMILIES} for r in range(N_ROWS)}
    for F in FAMILIES:
        if sorted(screens[F]["blocking_rows"]) != list(range(N_ROWS)): _fail(K, f"screen {F} does not cover the whole range exactly once")
    agg = aggregate_rows(fam_rows); lv = _levels_from_rows(N_ROWS, dict(cert["thresholds"]), agg)
    if sorted(int(k) for k in cert["rows"]) != list(range(N_ROWS)) or any(cert["rows"][str(r)]["families"] != fam_rows[r] or cert["rows"][str(r)]["levels"] != agg[r] or [(e.get("kind"), e.get("family"), e.get("source_sha256")) for e in cert["rows"][str(r)]["evidence"]] != [("screen", F, screens[F]["screen"]["content_sha256"]) for F in FAMILIES] for r in range(N_ROWS)): _fail(K, "certificate rows differ from the re-derivation from the authenticated screens")
