def _check_acceptance(root: str, screens: dict, certificate: dict) -> dict:
    K = "acceptance"; R = _root(root); base = os.path.join(R, "acceptance"); docs = _check_files(base, {k: dict(sha256=v["sha256"], bytes=v["bytes"]) for k, v in ACCEPTANCE.items()}, K)
    _, acc = _json(os.path.join(base, ACCEPTANCE_FILE)); _, dec = _json(os.path.join(base, DECISION_FILE)); _, st = _json(os.path.join(base, SETTINGS_FILE))
    G = acc.get("GO") or {}
    if acc.get("decision") != ACCEPTANCE_DECISION or G.get("screen_E2_E7_E8_run_evidence_acceptance") is not True or G.get("certificate_run_evidence_acceptance") is not True or G.get("fixed_campaign_usable_true_impossibility_acceptance_support") is not True or G.get("fixed_campaign_usable_true_impossibility_acceptance_strong") is not True or G.get("registration_drafting_and_tests_GO") is not True or G.get("formal_global_calibration_completed") is not False or G.get("formal_usable_false_measured") is not False or G.get("PhaseE_actual_target_or_labels") is not False or acc.get("requires_mandatory_code_patch") is not False: _fail(K, "acceptance document decision / GO flags")
    S = (acc.get("subject") or {}).get("execution_source") or {}
    if S.get("commit") != SOURCE["commit"] or S.get("engine") != SOURCE["engine_version"] or (S.get("inventory") or {}).get("sha256") != SOURCE["inventory"]["sha256"] or (S.get("script") or {}).get("sha256") != SOURCE["script_sha256"] or (S.get("pins") or {}).get("sha256") != SOURCE["pins_sha256"] or (S.get("source_zip") or {}).get("sha256") != SOURCE["source_zip_sha256"] or ((acc.get("subject") or {}).get("results_archive") or {}).get("sha256") != RESULTS["archive"]["sha256"]: _fail(K, "acceptance does not name the registered execution source / results archive")
    for F in FAMILIES:
        a = (acc.get("accepted_screens") or {}).get(F) or {}; C = SCREENS[F]
        if a.get("attempt") != C["attempt"] or a.get("n_rows") != N_ROWS or a.get("n_blocking") != C["screen"]["n_blocking"] or a.get("screen_content_sha256") != C["screen"]["content_sha256"] or (a.get("screen_file") or {}).get("sha256") != C["screen"]["sha256"] or (a.get("run_file") or {}).get("sha256") != C["run_file_sha256"] or (a.get("lock_file") or {}).get("sha256") != C["execution_lock"]["lock_file_sha256"] or (a.get("final_file") or {}).get("sha256") != C["final_file_sha256"] or (a.get("inner_zip") or {}).get("sha256") != C["archive"]["sha256"] or (a.get("notebook") or {}).get("sha256") != C["executed_notebook"]["sha256"] or a.get("max_ratio_by_size") != C["screen"]["ratio_bound_max"] or a.get("min_P") != C["screen"]["min_P"]: _fail(K, f"acceptance does not name the registered screen {F}")
    ac = acc.get("accepted_certificate") or {}
    if (ac.get("file") or {}).get("sha256") != CERTIFICATE["record_file"]["sha256"] or ac.get("content_sha256") != CERTIFICATE["content_sha256"] or ac.get("original_document_rederived_byte_exact") is not True: _fail(K, "acceptance does not name the registered certificate")
    fs = acc.get("formal_statement") or {}
    if fs.get("distinct_global_blocking_rows") != N_ROWS or fs.get("known_technical_rows_in_certificate") != 0 or fs.get("possibly_technical_rows") != N_ROWS or "W2 unknown by itself implies impossibility" not in (fs.get("not_claimed") or []): _fail(K, "acceptance formal statement scope")
    if dec.get("decision") != EXECUTION_DECISION or ((dec.get("fixed_source") or {}).get("inventory") or {}).get("sha256") != SOURCE["inventory"]["sha256"] or (dec.get("fixed_source") or {}).get("commit") != SOURCE["commit"] or (dec.get("GO") or {}).get("screen_E2_E7_E8_all_2000_execution") is not True or dec["GO"].get("certificate_after_three_complete_authenticated_screens") is not True: _fail(K, "execution decision does not name the registered source / GO")
    ce = st.get("common_editable_cell") or {}
    if ce.get("REPO_COMMIT") != SOURCE["commit"] or ce.get("EXPECTED_INVENTORY_SHA256") != SOURCE["inventory"]["sha256"] or ce.get("ROW_RANGE") is not None or ce.get("TARGET_COMMITMENT") != TARGET_COMMITMENT or ce.get("CAMPAIGN_ID") != CAMPAIGN_ID or any(((st.get("family_editable_cells") or {}).get(F) or {}).get("D2_RUN_ROOT") != SCREENS[F]["execution_lock"]["d2_run_root"] for F in FAMILIES) or ce.get("OUT_ROOT") != SCREENS["E2"]["execution_lock"]["out_root"]: _fail(K, "execution settings differ from the registered locks")
